def _stable_json(value: object) -> str:
    """把批次输入递归归一化为确定性 JSON 文本。

    映射键排序、元组按序列处理、:class:`Decimal` 按其精确字符串形式参与；
    不可 JSON 化的类型（如集合、自定义对象）向上抛出，由调用方转成
    “请求摘要无法计算”的标识无效结果。
    """

    def normalize(node: object) -> object:
        if node is None or isinstance(node, (bool, str, int)):
            return node
        if isinstance(node, Decimal):
            return {"__decimal__": str(node)}
        if isinstance(node, Mapping):
            return {
                str(key): normalize(node[key])
                for key in sorted(node, key=lambda k: str(k))
            }
        if isinstance(node, (list, tuple)):
            return [normalize(item) for item in node]
        raise TypeError(f"不支持请求摘要的输入类型: {type(node).__name__}")

    return json.dumps(
        normalize(value), ensure_ascii=False, sort_keys=True, separators=(",", ":")
    )


def _request_digest(
    kind: str,
    payload: Mapping[str, object],
) -> str:
    """计算批次完整请求内容的 sha256 摘要（十六进制文本）。"""
    canonical = json.dumps(
        {"kind": kind, "payload": json.loads(_stable_json(payload))},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    return sha256(canonical.encode("utf-8")).hexdigest()

